parameters.jsCode:
/* Satu node memegang setiap aturan yang menentukan apakah uang keluar.
   Urutannya disengaja dan penting:

     1. rekening vendor tidak ada  - tidak bisa membayar ke ketiadaan
     2. vendor ditahan (sanksi)    - halangan hukum, diperiksa sebelum urusan uang
     3. faktur sudah pernah dibayar- pembayaran ganda tidak bisa ditarik kembali
     4. rekening baru berubah      - penipuan pengalihan pembayaran
     5. nilai terlalu kecil        - biaya transfer melebihi manfaatnya
     6. kas tidak cukup            - ini penjadwalan, bukan penolakan, jadi paling akhir

   Nomor 4 adalah alasan utama workflow ini ada. Penipuan pembayaran yang
   berhasil hampir selalu berbentuk sama: email meminta "rekening kami ganti",
   lalu satu transfer besar hilang. Satu-satunya pertahanan yang bekerja adalah
   menahan pembayaran ketika nomor rekening berubah baru-baru ini, dan menelepon
   vendor lewat nomor lama - bukan nomor yang tertulis di email itu. */

const HARI_REKENING_BARU   = 14;
const PLAFON_TANPA_SENTUH  = 10000000;
const PLAFON_MANAJER       = 100000000;
const PLAFON_DIREKTUR      = 400000000;
const MIN_BAYAR            = 100000;

function toNum(v){ if(v===null||v===undefined||v==='') return 0;
  const n = Number(String(v).split(',').join('')); return isNaN(n)?0:n; }
function hariAntara(a,b){ const x=Date.parse(a), y=Date.parse(b);
  if(isNaN(x)||isNaN(y)) return null; return Math.round((y-x)/86400000); }
function samar(no){ const s=String(no||''); return s.length<5 ? '****' : '******'+s.slice(-4); }

const hariIni = new Date().toISOString().slice(0,10);

/* --- master --- */
const bankVendor = {};
for (const it of $('Muat Rekening Vendor').all()) {
  const r = it.json || {};
  if (r.vendor) bankVendor[String(r.vendor).trim().toUpperCase()] = r;
}

/* Hanya baris yang benar-benar dikembalikan tabel yang dihitung sebagai
   pembayaran terdahulu. Menghitung niat, bukan hasil, adalah cara paling mudah
   membayar dua kali. */
const sudahDibayar = {};
for (const it of $('Muat Pembayaran Sebelumnya').all()) {
  const r = it.json || {};
  const st = String(r.status||'');
  if (st !== 'settled' && st !== 'sent') continue;
  if (!r.vendor || !r.invoice_number) continue;
  sudahDibayar[String(r.vendor).trim().toUpperCase() + '|' + String(r.invoice_number).trim()] = r;
}

const akunArr = $('Muat Posisi Kas').all().map(function(i){ return i.json; })
  .filter(function(a){ return a && a.account_code; });
const akun = akunArr[0] || { account_code:'(tidak ada)', balance:0, min_buffer:0, cost_of_cash_pct:0, currency:'IDR' };
const saldo = toNum(akun.balance);
const buffer = toNum(akun.min_buffer);
const bolehPakai = Math.max(0, saldo - buffer);
const biayaKasPct = toNum(akun.cost_of_cash_pct);

/* --- faktur yang layak dibayar --- */
const faktur = [];
for (const it of $('Muat Faktur Disetujui').all()) {
  const r = it.json || {};
  const d = String(r.decision||'');
  if (d !== 'auto_approve' && d !== 'needs_approval') continue;
  const jml = toNum(r.amount);
  if (jml <= 0) continue;
  faktur.push(r);
}

/* Diskon bayar-awal hanya diambil kalau memang menguntungkan. "2/10 NET 30"
   berarti hemat 2% bila dibayar 20 hari lebih cepat; itu setara bunga tahunan
   sekitar 36%, jauh di atas biaya kas 12%, jadi layak diambil. Membandingkan
   keduanya - bukan sekadar melihat ada diskon - adalah bedanya bendahara yang
   berhitung dengan yang sekadar cepat membayar. */
function bacaTermin(teks){
  const t = String(teks||'NET 30').toUpperCase();
  const net = (t.match(/NET\s*(\d+)/)||[])[1];
  const disk = t.match(/(\d+(?:\.\d+)?)\s*\/\s*(\d+)/);
  return { netHari: net?parseInt(net,10):30,
           diskonPct: disk?parseFloat(disk[1]):0,
           diskonHari: disk?parseInt(disk[2],10):0 };
}

const keluar = [];
let dipakai = 0;

/* Urutan pembayaran: yang menghasilkan diskon dulu (itu uang nyata yang hilang
   kalau lewat tanggal), lalu yang paling tua. */
faktur.sort(function(a,b){
  const ta = bacaTermin((bankVendor[String(a.vendor||'').trim().toUpperCase()]||{}).payment_terms);
  const tb = bacaTermin((bankVendor[String(b.vendor||'').trim().toUpperCase()]||{}).payment_terms);
  if ((tb.diskonPct>0) !== (ta.diskonPct>0)) return tb.diskonPct>0 ? 1 : -1;
  return String(a.processed_at||'').localeCompare(String(b.processed_at||''));
});

for (const f of faktur) {
  const vendor = String(f.vendor||'').trim();
  const vKey = vendor.toUpperCase();
  const noFaktur = String(f.invoice_number||'').trim();
  const jml = toNum(f.amount);
  const bank = bankVendor[vKey] || null;
  const termin = bacaTermin(bank ? bank.payment_terms : 'NET 30');

  let status='', rute='', kodeTahan='', alasan='', diskon=0, bayarPada='';

  const umurFaktur = hariAntara(String(f.processed_at||'').slice(0,10), hariIni);
  const dalamJendelaDiskon = termin.diskonPct>0 && umurFaktur!==null && umurFaktur <= termin.diskonHari;
  const hematJika = Math.round(jml * termin.diskonPct / 100);
  const hariDipercepat = Math.max(0, termin.netHari - (umurFaktur||0));
  const biayaKas = Math.round(jml * (biayaKasPct/100) * (hariDipercepat/365));
  const diskonLayak = dalamJendelaDiskon && hematJika > biayaKas;

  const hariSejakUbah = bank ? hariAntara(bank.changed_on, hariIni) : null;

  if (!bank) {
    status='held'; rute='ap_clerk'; kodeTahan='NO_BANK_DETAILS';
    alasan='Tidak ada rekening terverifikasi untuk ' + vendor + '. Tidak ada tujuan transfer.';
  } else if (bank.sanctions_flag === true) {
    status='held'; rute='legal'; kodeTahan='SANCTIONS';
    alasan=vendor + ' sedang ditahan: ' + (bank.notes || 'ditandai pada daftar tahan') + ' Legal harus melepas dulu.';
  } else if (sudahDibayar[vKey + '|' + noFaktur]) {
    const lama = sudahDibayar[vKey + '|' + noFaktur];
    status='held'; rute='ap_supervisor'; kodeTahan='DUPLICATE';
    alasan='Faktur ini sudah dibayar pada ' + String(lama.settled_on || lama.pay_on || 'run sebelumnya')
      + ' (ref ' + String(lama.bank_ref||'-') + '). Membayarnya lagi tidak bisa ditarik kembali.';
  } else if (hariSejakUbah !== null && hariSejakUbah <= HARI_REKENING_BARU) {
    status='held'; rute='treasury'; kodeTahan='BANK_CHANGED';
    alasan='Nomor rekening ' + vendor + ' berubah ' + hariSejakUbah + ' hari lalu lewat '
      + String(bank.change_channel||'jalur tidak tercatat') + ' oleh ' + String(bank.changed_by||'tidak diketahui')
      + '. Telepon vendor memakai nomor LAMA yang tersimpan, bukan kontak apa pun di pesan yang meminta perubahan.';
  } else if (jml < MIN_BAYAR) {
    status='held'; rute='ap_clerk'; kodeTahan='TOO_SMALL';
    alasan='Nilainya ' + jml + ', di bawah ambang ' + MIN_BAYAR + '. Digabung ke run berikutnya.';
  } else if (dipakai + jml > bolehPakai) {
    status='held'; rute='treasury'; kodeTahan='CASH_SHORT';
    alasan='Kas yang boleh dipakai ' + bolehPakai + ' (saldo ' + saldo + ' dikurangi cadangan ' + buffer
      + '). Run ini sudah mengalokasikan ' + dipakai + ', sedangkan tagihan ini ' + jml + '. Ditunda, bukan ditolak.';
  } else {
    status='to_pay';
    diskon = diskonLayak ? hematJika : 0;
    bayarPada = hariIni;
    dipakai = dipakai + (jml - diskon);
    if (jml <= PLAFON_TANPA_SENTUH) rute='accounting_auto';
    else if (jml <= PLAFON_MANAJER) rute='manager';
    else if (jml <= PLAFON_DIREKTUR) rute='director';
    else rute='dual_signature';
  }

  keluar.push({ json: {
    line_key: 'RUN-' + String($execution.id||'manual') + '|' + vKey + '|' + noFaktur,
    run_key: 'RUN-' + String($execution.id||'manual'),
    vendor: vendor, invoice_number: noFaktur,
    amount: jml, currency: String(f.currency||'IDR'),
    status: status, route_to: rute, hold_code: kodeTahan, hold_reason: alasan,
    account_number_masked: bank ? samar(bank.account_number) : '',
    bank_name: bank ? String(bank.bank_name||'') : '',
    account_name: bank ? String(bank.account_name||'') : '',
    pay_on: bayarPada, discount_taken: diskon,
    bank_ref: '', settled_on: '', reject_reason: '',
    net_amount: jml - diskon,
    payment_terms: termin.diskonPct>0 ? (termin.diskonPct + '/' + termin.diskonHari + ' NET ' + termin.netHari) : ('NET ' + termin.netHari),
    diskon_tersedia: hematJika, diskon_layak: diskonLayak, biaya_kas: biayaKas,
    umur_faktur_hari: umurFaktur,
    butuh_tanda_tangan_ganda: rute === 'dual_signature',
    akun_sumber: akun.account_code,
    kas_boleh_dipakai: bolehPakai, kas_terpakai_sampai_baris_ini: dipakai,
    execution_id: String($execution.id||'manual')
  }});
}
return keluar;

