parameters.jsCode:
/* Bank membalas setelah berkas diproses. Sebagian baris lunas, sebagian
   ditolak - rekening tutup, nama tidak cocok, dana kurang. Balasan ini harus
   dibaca kembali, kalau tidak catatan kita mengklaim semuanya terbayar padahal
   tidak. Inilah bagian yang paling sering hilang dari otomasi pembayaran. */
const masuk = $input.all().map(function(i){ return i.json; });
const badan = (masuk[0] && (masuk[0].body || masuk[0])) || {};
const runKey = String(badan.run_key || '');
const hasil = Array.isArray(badan.results) ? badan.results : [];

if (!runKey || !hasil.length) {
  return [{ json: { _kosong: true, run_key: runKey,
    pesan: 'Balasan bank tidak memuat run_key atau daftar results.' } }];
}

return hasil.map(function(r){
  const st = String(r.status||'').toLowerCase();
  const lunas = st === 'settled' || st === 'paid' || st === 'ok';
  return { json: {
    run_key: runKey,
    vendor: String(r.vendor||''),
    invoice_number: String(r.invoice_number||''),
    line_key: runKey + '|' + String(r.vendor||'').trim().toUpperCase() + '|' + String(r.invoice_number||'').trim(),
    bank_ref: String(r.bank_ref||''),
    hasil_bank: lunas ? 'settled' : 'rejected',
    reject_reason: lunas ? '' : String(r.reason || 'ditolak bank tanpa alasan tertulis'),
    settled_on: lunas ? new Date().toISOString().slice(0,10) : '',
    amount: Number(r.amount||0)
  }};
});

/* Rekonsiliasi: apa yang dikirim vs apa yang benar-benar lunas. Selisihnya
   adalah uang yang dikira sudah terbayar padahal tidak, dan itu yang membuat
   vendor menelepon sebulan kemudian. */
function rp(n){ return Number(n||0).toLocaleString('id-ID'); }
const balasan = $('Kumpulkan Hasil Bank').all().map(function(i){ return i.json; });
const lunas = balasan.filter(function(r){ return r.hasil_bank==='settled'; });
const tolak = balasan.filter(function(r){ return r.hasil_bank==='rejected'; });
const runKey = String((balasan[0]||{}).run_key||'');

let tertulis = [];
try { tertulis = $('Perbarui Baris Pembayaran').all().map(function(i){ return i.json; })
      .filter(function(r){ return r && r.id !== undefined && r.id !== null; }); } catch(e) { tertulis = []; }

function jum(a){ return a.reduce(function(s,r){ return s + Number(r.amount||0); }, 0); }

return [{ json: {
  run_key: runKey,
  dibalas: balasan.length,
  lunas: lunas.length, nilai_lunas: jum(lunas),
  ditolak: tolak.length, nilai_ditolak: jum(tolak),
  baris_diperbarui: tertulis.length,
  baris_gagal_diperbarui: balasan.length - tertulis.length,
  daftar_tolak: tolak.map(function(r){
    return { vendor:r.vendor, faktur:r.invoice_number, nilai:r.amount, alasan:r.reject_reason };
  }),
  ringkas: lunas.length + ' lunas (' + rp(jum(lunas)) + ' IDR), '
    + tolak.length + ' ditolak (' + rp(jum(tolak)) + ' IDR)'
}}];

